    w.p(f"Ж, с. {anchors['ПРИЛОЖЕНИЕ Ж']}, связывает все 15 листьев с операциями и средствами. Д, с. {anchors['ПРИЛОЖЕНИЕ Д']}, задаёт 11 модулей. И, с. {anchors['ПРИЛОЖЕНИЕ И']}, содержит поля, типы, кодирование, ошибки и примеры. Полные индивидуальные задания — contracts/module_tasks.json.")

    w.structural('Точные ответы на спорные вопросы')
    for title,text in [
      ('Откуда 20 процентов','Это предложенная проектная норма для согласования. Она не взята из слов преподавателя и не является замером банка. 30 пар и 120 секунд также являются условиями проекта.'),
      ('Что именно подтверждает качество','Не количество диаграмм и не один успешный модуль. Нужны верные полные обращения, нормы труда и времени, предметные эталоны и свидетельства. ПМИ описывает способ проверки; соответствие подтверждают результаты её выполнения.'),
      ('Что с рабочей документацией','Требование о документации по каждому модулю в записи есть. Задания 11 модулей уточнены до входов, результатов, условий, ошибок и проверок. Это технический проект; полного комплекта РКД, кода всех форм и фактических протоколов ещё нет.'),
      ('Нужен ли уже готовый код','Доступная запись не устанавливает точный срок реализации. Фраза «Если бы у вас был…» обсуждает приёмку готового продукта. Не следует говорить, будто преподаватель разрешил вообще не писать программу.'),
      ('Какие слова нельзя ему приписывать','«Внеактивное» — вероятная ошибка ASR; два новых прохода дали «внятное». Конкретная буква приложения, обязательный стек и точное выражение «принципы развития» в этих записях не установлены. Содержание развития и восемь приложений при этом сохранены.')]:
        w.h(title);w.p(text)
    w.p(f'Основная записка: {len(texts)} страниц. Этот материал отдельный; печатать его вместе с запиской не требуется.',size=11,indent=0,before=5)
    w.save(NOTE)
    print(json.dumps({'main_pages':len(texts),'note':str(NOTE),'direct_quote_checks':len(rows),'additional_checks':len(extra)},ensure_ascii=False))

